MODELS = {
    'EC2': 'IaaS', 'EBS': 'IaaS', 'VPC': 'IaaS',
    'RDS': 'PaaS', 'Lambda': 'PaaS', 'Elastic Beanstalk': 'PaaS', 'DynamoDB': 'PaaS',
    'WorkDocs': 'SaaS', 'Chime': 'SaaS', 'QuickSight': 'SaaS',
}


def cloud_model(service):
    return MODELS.get(service, 'UNKNOWN')

def usable_subnet_ips(mask):
    if not 16 <= mask <= 28:
        return 0
    return 2 ** (32 - mask) - 5

def security_group_allows(rules, traffic):
    if traffic.get('is_return'):
        return True
    return any(
        rule['protocol'] == traffic['protocol'] and rule['from_port'] <= traffic['port'] <= rule['to_port']
        for rule in rules
    )

def nacl_decision(rules, port):
    for rule in sorted(rules, key=lambda r: r['rule_number']):
        if rule['port'] == '*' or rule['port'] == port:
            return rule['action']
    return 'DENY'

def validate_vpc(vpc):
    subnets = vpc['subnets']
    azs = {s['az'] for s in subnets}
    public = sum(1 for s in subnets if s['type'] == 'PUBLIC')
    private = sum(1 for s in subnets if s['type'] == 'PRIVATE')
    problems = []
    if len(azs) < 2:
        problems.append('NEEDS_2_AZS')
    if public < 2:
        problems.append('NEEDS_2_PUBLIC_SUBNETS')
    if private < 2:
        problems.append('NEEDS_2_PRIVATE_SUBNETS')
    if not vpc['has_internet_gateway']:
        problems.append('NO_INTERNET_GATEWAY')
    if not vpc['has_nat_gateway']:
        problems.append('NO_NAT_GATEWAY')
    return {'valid': not problems, 'az_count': len(azs), 'problems': problems}

import ipaddress


def subnets_distinct(cidrs):
    nets = [ipaddress.ip_network(c) for c in cidrs]
    for i in range(len(nets)):
        for j in range(i + 1, len(nets)):
            if nets[i].overlaps(nets[j]):
                return False
    return True

def matches(pattern, value):
    if pattern.endswith('*'):
        return value.startswith(pattern[:-1])
    return pattern == value


def evaluate_iam(statements, request):
    hits = [s for s in statements if matches(s['action'], request['action']) and matches(s['resource'], request['resource'])]
    if any(s['effect'] == 'Deny' for s in hits):
        return 'DENY'
    if any(s['effect'] == 'Allow' for s in hits):
        return 'ALLOW'
    return 'DENY'

def parse_arn(arn):
    parts = arn.split(':', 5)
    if len(parts) != 6 or parts[0] != 'arn':
        return None
    _, partition, service, region, account, resource = parts
    return {'partition': partition, 'service': service, 'region': region, 'account': account, 'resource': resource}

import math


def desired_capacity(current, metric, target, min_size, max_size):
    wanted = math.ceil(current * metric / target)
    return max(min_size, min(max_size, wanted))

def spot_action(seconds_notice):
    if seconds_notice <= 0:
        return 'ALREADY_GONE'
    if seconds_notice <= 120:
        return 'DRAIN_NOW'
    return 'KEEP_WORKING'

def route_alb(rules, path):
    for rule in rules:
        pattern = rule['pattern']
        if pattern.endswith('*'):
            if path.startswith(pattern[:-1]):
                return rule['target_group']
        elif pattern == path:
            return rule['target_group']
    return 'tg-default'

def target_state(results, healthy_threshold=3, unhealthy_threshold=2):
    state, passes, failures = 'UNHEALTHY', 0, 0
    for ok in results:
        if ok:
            passes, failures = passes + 1, 0
            if passes >= healthy_threshold:
                state = 'HEALTHY'
        else:
            passes, failures = 0, failures + 1
            if failures >= unhealthy_threshold:
                state = 'UNHEALTHY'
    return state

def storage_class(age_days, access):
    if age_days >= 365:
        return 'DEEP_ARCHIVE'
    if age_days >= 90:
        return 'GLACIER_FLEXIBLE'
    if age_days >= 30 and access == 'INFREQUENT':
        return 'STANDARD_IA'
    return 'STANDARD'

def current_version(versions):
    if not versions or versions[-1]['is_delete_marker']:
        return None
    return versions[-1]['version_id']

def enforces_tls(policy):
    for s in policy.get('Statement', []):
        if s.get('Effect') == 'Deny' and s.get('Condition', {}).get('Bool', {}).get('aws:SecureTransport') == 'false':
            return True
    return False

import re


def is_valid_bucket_name(name):
    if not re.fullmatch(r'[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]', name):
        return False
    if '..' in name:
        return False
    return not re.fullmatch(r'\d+\.\d+\.\d+\.\d+', name)

def lambda_cost(invocations, duration_ms, memory_mb):
    gb_seconds = invocations * (duration_ms / 1000) * (memory_mb / 1024)
    return round(gb_seconds * 0.0000166667 + invocations / 1_000_000 * 0.20, 4)

def concurrency_model(cold_start_ms, latency_critical):
    if not latency_critical:
        return 'ON_DEMAND'
    if cold_start_ms > 200:
        return 'PROVISIONED'
    if cold_start_ms > 100:
        return 'SNAPSTART'
    return 'ON_DEMAND'

def authorizer_response(principal_id, effect, resource_arn):
    if effect not in ('Allow', 'Deny'):
        raise ValueError('effect must be Allow or Deny')
    return {
        'principalId': principal_id,
        'policyDocument': {
            'Version': '2012-10-17',
            'Statement': [{'Action': 'execute-api:Invoke', 'Effect': effect, 'Resource': resource_arn}],
        },
    }

def cors_headers(origin, allowed_origins):
    if origin not in allowed_origins:
        return {}
    return {
        'Access-Control-Allow-Origin': origin,
        'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type,Authorization',
        'Vary': 'Origin',
    }

from collections import Counter


def hot_keys(access_log, share=0.5):
    if not access_log:
        return []
    total = len(access_log)
    return sorted(key for key, n in Counter(access_log).items() if n / total > share)

import math


def required_rcu(item_size_bytes, reads_per_sec, strongly_consistent):
    units = math.ceil(item_size_bytes / 4096) * reads_per_sec
    if not strongly_consistent:
        units = units / 2
    return math.ceil(units)

def failover(cluster):
    if not cluster['multi_az'] or not cluster['standby_az']:
        return {'success': False, 'new_primary': None}
    cluster['primary_az'], cluster['standby_az'] = cluster['standby_az'], cluster['primary_az']
    return {'success': True, 'new_primary': cluster['primary_az']}

def route_query(sql, primary, replicas, counter):
    if sql.strip().upper().startswith('SELECT') and replicas:
        return replicas[counter % len(replicas)]
    return primary

def process_upload(event, db, transcode):
    done = failed = 0
    for record in event.get('Records', []):
        bucket = record['s3']['bucket']['name']
        key = record['s3']['object']['key']
        try:
            url = transcode(bucket, key)
            db[key] = {'bucket': bucket, 'output_url': url, 'status': 'DONE'}
            done += 1
        except Exception:
            db[key] = {'bucket': bucket, 'output_url': None, 'status': 'FAILED'}
            failed += 1
    return {'processed': done, 'failed': failed}

def parse_s3_record(record):
    obj = record['s3']['object']
    return {
        'bucket': record['s3']['bucket']['name'],
        'key': obj['key'].replace('+', ' ').replace('%20', ' '),
        'size': obj['size'],
    }

def edge_ttl(cache_control, default_ttl=86400):
    directives = [d.strip() for d in cache_control.split(',') if d.strip()]
    if 'no-store' in directives or 'private' in directives:
        return 0
    for name in ('s-maxage=', 'max-age='):
        for d in directives:
            if d.startswith(name):
                return int(d[len(name):])
    return default_ttl

def cache_key(path, headers, query, key_headers, key_params):
    lower = {name.lower(): value for name, value in headers.items()}
    kept_headers = sorted((name, lower[name]) for name in key_headers if name in lower)
    kept_params = sorted((name, query[name]) for name in key_params if name in query)
    join = lambda pairs: '&'.join(f'{n}={v}' for n, v in pairs)
    return f'{path}|{join(kept_headers)}|{join(kept_params)}'

def resolve_dns(config, health):
    primary = config['primary']
    if config['policy'] == 'SIMPLE':
        return primary
    if health.get(primary, False):
        return primary
    secondary = config.get('secondary')
    if secondary and health.get(secondary, False):
        return secondary
    return primary

def pick_weighted(records, roll):
    total = 0
    for record in records:
        total += record['weight']
        if roll < total:
            return record['endpoint']
    return None

class Queue:
    def __init__(self, visibility_timeout=30):
        self.visibility_timeout = visibility_timeout
        self.messages = []
        self.next_id = 1

    def send(self, body):
        self.messages.append({'id': f'm{self.next_id}', 'body': body, 'receive_count': 0, 'visible_at': 0})
        self.next_id += 1

    def receive(self, now):
        for m in self.messages:
            if m['visible_at'] <= now:
                m['visible_at'] = now + self.visibility_timeout
                m['receive_count'] += 1
                return {'id': m['id'], 'body': m['body'], 'receive_count': m['receive_count']}
        return None

    def delete(self, message_id):
        self.messages = [m for m in self.messages if m['id'] != message_id]

def accept_messages(messages, window=300):
    last_accepted, accepted = {}, []
    for dedup_id, t in messages:
        if dedup_id not in last_accepted or t - last_accepted[dedup_id] >= window:
            last_accepted[dedup_id] = t
            accepted.append(dedup_id)
    return accepted

def fanout(subscriptions, message, deliver):
    delivered, failed, skipped = [], [], 0
    for sub in subscriptions:
        if sub['status'] != 'CONFIRMED':
            skipped += 1
            continue
        try:
            deliver(sub['endpoint'], message)
            delivered.append(sub['endpoint'])
        except Exception:
            failed.append(sub['endpoint'])
    return {'delivered': delivered, 'failed': failed, 'skipped': skipped}

def match_pattern(pattern, event):
    for key, want in pattern.items():
        if key not in event:
            return False
        if isinstance(want, dict):
            if not isinstance(event[key], dict) or not match_pattern(want, event[key]):
                return False
        elif event[key] not in want:
            return False
    return True

def make_event(source, detail_type, detail, event_id, time):
    if '.' not in source or source.startswith('aws.'):
        raise ValueError('source must look like company.service and not start with aws.')
    return {'version': '0', 'id': event_id, 'source': source, 'detail-type': detail_type, 'time': time, 'detail': detail}

def route_event(event, rules, queues):
    matched = dead = delivered = 0
    for rule in rules:
        if rule['source'] == event['source'] and rule['detail_type'] == event['detail-type']:
            matched += 1
            if rule['target'] in queues:
                queues[rule['target']].append(event)
                delivered += 1
            else:
                dead += 1
    return {'matched': matched, 'dead_letters': dead, 'status': 'ROUTED' if delivered else 'NO_MATCH'}

