def container_env(plain, secrets):
    if set(plain) & set(secrets):
        raise ValueError('a name cannot be both a plain setting and a secret')
    return {
        'environment': [{'name': n, 'value': plain[n]} for n in sorted(plain)],
        'secrets': [{'name': n, 'valueFrom': secrets[n]} for n in sorted(secrets)],
    }

def run_saga(steps):
    done = []
    for step in steps:
        try:
            step['do']()
        except Exception:
            undone = []
            for prev in reversed(done):
                prev['undo']()
                undone.append(prev['name'])
            return {'success': False, 'failed_step': step['name'], 'undone': undone}
        done.append(step)
    return {'success': True, 'failed_step': None, 'undone': []}

VALID_TYPES = {'Task', 'Choice', 'Parallel', 'Map', 'Pass', 'Wait', 'Succeed', 'Fail'}


def validate_state_machine(definition):
    states = definition['States']
    problems = []
    if definition['StartAt'] not in states:
        problems.append('BAD_START')
    for name, state in states.items():
        if state.get('Type') not in VALID_TYPES:
            problems.append(f'BAD_TYPE:{name}')
        if 'Next' in state and state['Next'] not in states:
            problems.append(f'BAD_NEXT:{name}')
    return sorted(problems)

def parse_tf_address(address):
    parts = address.split('.')
    modules = []
    while parts[0] == 'module':
        modules.append(parts[1])
        parts = parts[2:]
    return {'modules': modules, 'type': parts[0], 'name': parts[1]}

def plan_summary(changes):
    add = change = destroy = 0
    replace = []
    for c in changes:
        actions = c['actions']
        if 'create' in actions:
            add += 1
        if 'delete' in actions:
            destroy += 1
        if 'update' in actions:
            change += 1
        if 'create' in actions and 'delete' in actions:
            replace.append(c['address'])
    return {'add': add, 'change': change, 'destroy': destroy, 'replace': sorted(replace)}

def alarm_state(datapoints, threshold, operator, periods):
    if len(datapoints) < periods:
        return 'INSUFFICIENT_DATA'
    recent = datapoints[-periods:]
    if operator == 'GreaterThanThreshold':
        breached = all(v > threshold for v in recent)
    else:
        breached = all(v < threshold for v in recent)
    return 'ALARM' if breached else 'OK'

from collections import Counter


def error_summary(logs, min_status=500):
    counts = Counter(entry['path'] for entry in logs if entry['status'] >= min_status)
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))

def xor_bytes(data, key):
    return bytes(b ^ key[i % len(key)] for i, b in enumerate(data))


def envelope_encrypt(plaintext, data_key, master_key, key_id):
    return {
        'ciphertext': xor_bytes(plaintext.encode(), data_key).hex(),
        'encrypted_data_key': xor_bytes(data_key, master_key).hex(),
        'key_id': key_id,
    }


def envelope_decrypt(envelope, master_key):
    data_key = xor_bytes(bytes.fromhex(envelope['encrypted_data_key']), master_key)
    return xor_bytes(bytes.fromhex(envelope['ciphertext']), data_key).decode()

def key_policy_risks(policy):
    risks = set()
    for s in policy.get('Statement', []):
        if s.get('Effect') != 'Allow':
            continue
        principal = s.get('Principal')
        if isinstance(principal, dict):
            principal = principal.get('AWS')
        if principal == '*' and not s.get('Condition'):
            risks.add('PUBLIC_PRINCIPAL')
        if s.get('Action') == 'kms:*' and not str(principal).endswith(':root'):
            risks.add('KMS_WILDCARD')
    return sorted(risks)

SQLI_SIGNS = ["' or 1=1", 'union select', '; drop table', '--']


def inspect_request(rules, request):
    for rule in rules:
        kind = rule['type']
        if kind == 'IP_BLOCK' and request['ip'] in rule['ips']:
            return {'action': 'BLOCK', 'rule': kind}
        if kind == 'SQLI' and any(sign in request['query'].lower() for sign in SQLI_SIGNS):
            return {'action': 'BLOCK', 'rule': kind}
        if kind == 'RATE_LIMIT' and request['count_5min'] > rule['limit']:
            return {'action': 'BLOCK', 'rule': kind}
    return {'action': 'ALLOW', 'rule': None}

import ipaddress


def valid_ip_set(ranges):
    if not ranges:
        return False
    for r in ranges:
        if '/' not in r:
            return False
        try:
            ipaddress.ip_network(r, strict=True)
        except ValueError:
            return False
    return True

def untagged_resources(resources, required):
    report = {}
    for r in resources:
        missing = sorted(tag for tag in required if not r['tags'].get(tag))
        if missing:
            report[r['id']] = missing
    return report

TIERS = [('BackupAndRestore', 1440, 60), ('PilotLight', 60, 10), ('WarmStandby', 5, 1)]


def dr_strategy(rto_minutes, rpo_minutes):
    for name, rto, rpo in TIERS:
        if rto_minutes >= rto and rpo_minutes >= rpo:
            return name
    return 'MultiSiteActiveActive'

def outage_cost(rto_minutes, rpo_minutes, orders_per_minute, order_value):
    per_minute = orders_per_minute * order_value
    lost_sales = rto_minutes * per_minute
    lost_data = rpo_minutes * per_minute
    return {'lost_sales': lost_sales, 'lost_data': lost_data, 'total': lost_sales + lost_data}

def route_transaction(regions, txn):
    ok = [r for r in regions if r['healthy'] and txn['country'] in r['allowed_countries']]
    if not ok:
        return {'success': False, 'region': None}
    best = min(ok, key=lambda r: r['latency_ms'])
    return {'success': True, 'region': best['code']}

def readiness_audit(checks):
    score = checks.get('finops_score', 0)
    flags = {name: ok for name, ok in checks.items() if name != 'finops_score'}
    failed = sorted(name for name, ok in flags.items() if not ok)
    certified = bool(flags) and not failed and score >= 80
    if certified:
        grade = 'TIER_1'
    elif flags and len(failed) <= 1 and score >= 60:
        grade = 'TIER_2'
    else:
        grade = 'NOT_READY'
    return {'certified': certified, 'failed': failed, 'grade': grade}
